package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
	"unicode"
)

type InputReader struct {
	scanner *bufio.Scanner
}

func NewInputReader() *InputReader {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	return &InputReader{scanner: scanner}
}

func (ir *InputReader) NextString() string {
	if ir.scanner.Scan() {
		return ir.scanner.Text()
	}
	return ""
}

func (ir *InputReader) NextInt32() int {
	var x int
	fmt.Sscan(ir.NextString(), &x)
	return x
}

func main() {
	sr := NewInputReader()
	sw := bufio.NewWriter(os.Stdout)
	defer sw.Flush()

	n := sr.NextInt32()
	_ = n
	str := sr.NextString()

	max := 0
	runes := []rune(str)
	for i := 0; i < len(runes); i++ {
		if unicode.IsLower(runes[i]) {
			set := make(map[rune]struct{})
			for j := i; j < len(runes); j++ {
				if unicode.IsLower(runes[j]) {
					set[runes[j]] = struct{}{}
				} else {
					break
				}
			}
			if len(set) > max {
				max = len(set)
			}
		}
	}

	fmt.Fprintln(sw, max)
}

// The following functions are included to mirror the structure of the C# InputReader,
// though they are not used in the main logic.

func (ir *InputReader) NextInt64() int64 {
	var x int64
	fmt.Sscan(ir.NextString(), &x)
	return x
}

func (ir *InputReader) ReadArrayOfInt32() []int {
	line := ir.nextLine()
	if line == "" {
		return nil
	}
	parts := strings.Fields(line)
	res := make([]int, len(parts))
	for i, p := range parts {
		fmt.Sscan(p, &res[i])
	}
	return res
}

func (ir *InputReader) ReadArrayOfInt64() []int64 {
	line := ir.nextLine()
	if line == "" {
		return nil
	}
	parts := strings.Fields(line)
	res := make([]int64, len(parts))
	for i, p := range parts {
		fmt.Sscan(p, &res[i])
	}
	return res
}

func (ir *InputReader) nextLine() string {
	reader := bufio.NewReader(os.Stdin)
	line, _ := reader.ReadString('\n')
	return strings.TrimSpace(line)
}

